// Scripted "how it works" flows for the explore view, one per service. A flow lists the
// models on its stage and a sequence of steps; see engine/exploreScene.js for the actions.
// Positions are in metres on a stage centred at the origin; things standing on an AZ
// platform use y = 0.25 (the platform's top).

const OK = '#4ade80';
const REQ = '#fbbf24';
const DB = '#f472b6';
const DNS = '#c4b5fd';
const BAD = '#f87171';
const PURPLE = '#a78bfa';
const CYAN = '#22d3ee';

const pk = (from, to, o = {}) => ({ do: 'packet', from, to, ...o });
const co = (node, text, kind = 'info', o = {}) => ({ do: 'callout', node, text, kind, ...o });
const at = (t, a) => ({ ...a, at: t });
const show = (node, t = 0) => ({ do: 'show', node, at: t });
const hide = (node, t = 0) => ({ do: 'hide', node, at: t });
const state = (node, value, t = 0) => ({ do: 'state', node, value, at: t });
const load = (node, value, t = 0) => ({ do: 'load', node, value, at: t });
const count = (node, value, t = 0) => ({ do: 'count', node, value, at: t });
// one packet from `from` to each node in `ids`: a write fanning out to copies, a command to a fleet…
const fan = (from, ids, o = {}) => ids.map((id) => pk(from, id, o));
// the six copies of an Aurora cluster volume, two per AZ
const COPIES = ['c1', 'c2', 'c3', 'c4', 'c5', 'c6'];

// Shared Responsibility stacks, bottom to top: [layer, who looks after it]
const HW = ['Trung tâm dữ liệu & phần cứng', 'aws'];
const NET = ['Mạng toàn cầu & ảo hoá', 'aws'];
const DATA = ['Dữ liệu của bạn', 'you'];
const FIREWALL = ['Tường lửa · mã hoá · IAM', 'you'];
const EC2_LAYERS = [HW, NET, ['Hệ điều hành & bản vá', 'you'], ['Ứng dụng & phần mềm', 'you'], FIREWALL, DATA];
const RDS_LAYERS = [HW, NET, ['Hệ điều hành & DB engine', 'aws'], ['Backup · Multi-AZ', 'both'], FIREWALL, DATA];
const LAMBDA_LAYERS = [HW, NET, ['Hệ điều hành & runtime', 'aws'], ['Mở rộng & sẵn sàng', 'aws'], ['Code & quyền IAM', 'you'], DATA];
// IaaS / PaaS / SaaS: the same six layers, more of them handed over at each step
const IAAS_LAYERS = [HW, NET, ['Hệ điều hành & bản vá', 'you'], ['Runtime & phần mềm', 'you'], ['Ứng dụng của bạn', 'you'], DATA];
const PAAS_LAYERS = [HW, NET, ['Hệ điều hành & bản vá', 'aws'], ['Runtime & phần mềm', 'aws'], ['Ứng dụng của bạn', 'you'], DATA];
const SAAS_LAYERS = [
  ['Trung tâm dữ liệu & phần cứng', 'vendor'],
  ['Mạng toàn cầu & ảo hoá', 'vendor'],
  ['Hệ điều hành & bản vá', 'vendor'],
  ['Runtime & phần mềm', 'vendor'],
  ['Ứng dụng: email, kế toán…', 'vendor'],
  ['Dữ liệu & tài khoản người dùng', 'you'],
];

