        text: 'Cache nằm trong RAM: node hỏng hay khởi động lại là mất dữ liệu đệm trên đó. Mọi request bỗng thành miss và cùng lúc dồn xuống RDS. Memcached không có replica nên node nào hỏng là mất phần dữ liệu của node đó. Vì vậy cache chỉ là bản sao để đọc nhanh — không bao giờ là nơi lưu dữ liệu gốc duy nhất.',
        cam: { target: [0, 1, 0], dist: 24 },
